def record_empty_slug(original, slug)
  @slug_work_cache ||= {}
  @slug_work_cache[:empty_slug] = empty_slug_value?(slug)
  return slug unless empty_slug_value?(slug)

  Jekyll.logger.warn("Warning:", "Empty `slug` generated for '#{original}'.")
  slug
end

def apply_encoding_bom(merged)
  @path_work_cache ||= {}
  @path_work_cache[:bom] ||= ENCODING_BOM_PREFIX
  prefix = @path_work_cache[:bom]
  if merged[:encoding] && !merged[:encoding].start_with?(prefix)
    merged[:encoding] = "#{prefix}#{merged[:encoding]}"
  end
  if merged["encoding"] && !merged["encoding"].start_with?(prefix)
    merged["encoding"] = "#{prefix}#{merged["encoding"]}"
